import app from 'flarum/common/app';
import { extend, override } from 'flarum/common/extend';
import { getIPData } from '../helpers/IPDataHelper';
import Tooltip from 'flarum/common/components/Tooltip';
import Button from 'flarum/common/components/Button';
import { handleCopyIP } from '../helpers/ClipboardHelper';
import MapModal from '../components/MapModal';
export default function extendIpAddress() {
  extend('flarum/common/components/IPAddress', 'viewItems', function (items) {
    if (!this.ipInfo) {
      this.loadIpInfo();
    }
    if (this.ipInfo && items.has('ip')) {
      items.remove('ip');
      const {
        description,
        threat,
        image
      } = getIPData(this.ipInfo);
      items.add('ipInfo', m("span", {
        className: "ip-info"
      }, image, m(Tooltip, {
        text: "".concat(description, " ").concat(threat ? "(".concat(threat, ")") : '')
      }, m("code", null, this.ip))), 100);
      items.add('copyButton', m(Tooltip, {
        text: app.translator.trans('fof-geoip.forum.copy_ip_label')
      }, m(Button, {
        icon: "fas fa-copy",
        className: "Button Button--icon Button--link",
        onclick: handleCopyIP(this.ip),
        "aria-label": app.translator.trans('fof-geoip.forum.copy_ip_label')
      })), 95);
      items.add('infoButton', m(Tooltip, {
        text: app.translator.trans('fof-geoip.forum.map_button_label')
      }, m(Button, {
        icon: "fas fa-info-circle",
        className: "Button Button--icon Button--link",
        onclick: e => {
          e.stopPropagation();
          app.modal.show(MapModal, {
            ipInfo: this.ipInfo,
            ipAddr: this.ip
          });
        },
        "aria-label": app.translator.trans('fof-geoip.forum.map_button_label')
      })), 90);
    }
  });
  override('flarum/common/components/IPAddress', 'view', function () {
    return m("span", {
      className: "IPAddress IPAddress--enhanced ip-container"
    }, this.viewItems().toArray());
  });
  extend('flarum/common/components/IPAddress', 'oninit', function () {
    this.loadIpInfo = async function () {
      if (this.ip.length === 0) return;
      try {
        // Try to get from store first
        let ipInfo = app.store.getBy('ip_info', 'ip', this.ip);

        // If not in store, fetch from API
        if (!ipInfo) {
          ipInfo = await app.store.find('ip_info', encodeURIComponent(this.ip));
        }
        this.ipInfo = ipInfo;
        m.redraw();
      } catch (error) {
        console.error('Failed to load IP info:', error);
      }
    };
  });
}
flarum.reg.add('fof-geoip', 'common/extenders/extendIpAddress', extendIpAddress);